var n=`0690-binch-akara`;var t=`world-0690`;var a=`SL`;var o=`western-africa`;var s=4;var r=520;var l={en:`Binch Akara`,ua:`Бінч акара`};var d={en:`Binch Akara is a Sierra Leone classic prepared with black-eyed peas, yellow onion, scotch bonnet pepper. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Бінч акара, страва кухні країни Сьєрра-Леоне зі складниками: квасоля чорноочка, жовта цибуля, перець скотч-боннет. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var h=[{en:`Soak the dried beans or peas in plentiful cold water for 480 minutes, then drain and discard the soaking liquid; keep refrigerated in hot conditions.`,ua:`Замочіть сухі бобові у великій кількості холодної води на 480 хвилин, після чого злийте й вилийте воду від замочування; за спеки тримайте в холодильнику.`,t:[`soaking-legumes`],m:480,i:[[`black-eyed-peas`,380,`g`],[`water`,850,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:15,i:[[`yellow-onion`,190,`g`],[`scotch-bonnet-pepper`,1,`pcs`],[`table-salt`,5,`g`],[`water`,160,`ml`]]},{en:`Whisk or whip the listed ingredients to a smooth, light consistency, then keep cool until needed.`,ua:`Збийте зазначені складники до гладкої легкої консистенції, після чого зберігайте в прохолоді до використання.`,t:[`whipping`],m:7,i:[]},{en:`Fry shaped portions in small batches in oil heated to about 170–175°C for about 18 minutes, until golden; drain on a rack.`,ua:`Смажте сформовані вироби невеликими партіями в олії температурою приблизно 170–175°C близько 18 хвилин до золотистості; викладіть на решітку.`,t:[`deep-frying`],m:18,i:[[`sunflower-oil`,700,`ml`]]}];var c={slug:n,id:t,country:`SL`,region:o,servings:4,minutes:520,title:l,text:d,steps:h};export{a as country,c as default,t as id,r as minutes,o as region,s as servings,n as slug,h as steps,d as text,l as title};